--

COMMENT ON COLUMN public.external_league_import_jobs.job_id IS 'Unique identifier for the import job';


--
-- Name: COLUMN external_league_import_jobs.connection_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.external_league_import_jobs.connection_id IS 'Reference to the external league connection';


--
-- Name: COLUMN external_league_import_jobs.job_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.external_league_import_jobs.job_type IS 'Type of sync operation to perform';


--
-- Name: COLUMN external_league_import_jobs.sync_components; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.external_league_import_jobs.sync_components IS 'JSON configuration of which components to sync';


--
-- Name: COLUMN external_league_import_jobs.status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.external_league_import_jobs.status IS 'Current job status: queued, running, completed, failed, cancelled';


--
-- Name: COLUMN external_league_import_jobs.progress_percentage; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.external_league_import_jobs.progress_percentage IS 'Job completion percentage (0-100)';


--
-- Name: COLUMN external_league_import_jobs.current_step; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.external_league_import_jobs.current_step IS 'Human-readable description of current processing step';


--
-- Name: COLUMN external_league_import_jobs.results; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.external_league_import_jobs.results IS 'JSON containing detailed job results';


--
-- Name: COLUMN external_league_import_jobs.raw_data; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.external_league_import_jobs.raw_data IS 'Raw data from external platform (for debugging)';


--
-- Name: COLUMN external_league_import_jobs.mapped_data; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.external_league_import_jobs.mapped_data IS 'Processed/mapped data (for debugging)';


--
-- Name: external_league_memberships; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.external_league_memberships (
    platform character varying(20) NOT NULL,
    external_league_id character varying(64) NOT NULL,
    external_user_id character varying(64) NOT NULL,
    first_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    is_owner boolean
);


--
-- Name: TABLE external_league_memberships; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.external_league_memberships IS 'Manager-to-league edges of the external-league crawl graph. The expensive artifact: each edge cost a request to acquire, and together they make the frontier resumable and the same manager detectable across leagues.';


--
-- Name: COLUMN external_league_memberships.is_owner; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.external_league_memberships.is_owner IS 'null = member list not yet crawled for this league; only /league/{id}/users populates it';


--
-- Name: external_league_trade_legs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.external_league_trade_legs (
    platform character varying(20) NOT NULL,
    external_transaction_id character varying(64) NOT NULL,
    leg_index smallint NOT NULL,
    leg_type character varying(10) NOT NULL,
    from_roster_id smallint,
    to_roster_id smallint NOT NULL,
    pid character varying(25),
    external_player_id character varying(32),
    pick_season_year smallint,
    pick_round smallint,
    pick_original_roster_id smallint,
    free_agent_acquisition_budget_amount integer,
    CONSTRAINT external_league_trade_legs_leg_type_check CHECK (((leg_type)::text = ANY ((ARRAY['player'::character varying, 'pick'::character varying, 'faab'::character varying])::text[]))),
    CONSTRAINT external_league_trade_legs_payload_check CHECK (((((leg_type)::text = 'player'::text) AND (external_player_id IS NOT NULL) AND (pick_round IS NULL) AND (free_agent_acquisition_budget_amount IS NULL)) OR (((leg_type)::text = 'pick'::text) AND (pick_season_year IS NOT NULL) AND (pick_round IS NOT NULL) AND (external_player_id IS NULL) AND (pid IS NULL) AND (free_agent_acquisition_budget_amount IS NULL)) OR (((leg_type)::text = 'faab'::text) AND (free_agent_acquisition_budget_amount IS NOT NULL) AND (external_player_id IS NULL) AND (pid IS NULL) AND (pick_round IS NULL))))
);


--
-- Name: TABLE external_league_trade_legs; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.external_league_trade_legs IS 'Individual assets moved by an external trade: players, future draft picks, and FAAB. Grouping by to_roster_id yields the bundle each side received.';


--
-- Name: external_league_trades; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.external_league_trades (
    platform character varying(20) NOT NULL,
    external_transaction_id character varying(64) NOT NULL,
    external_league_id character varying(64) NOT NULL,
    season_year smallint NOT NULL,
    platform_transaction_bucket smallint NOT NULL,
    processed_at timestamp with time zone NOT NULL,
    number_sides smallint NOT NULL,
    imported_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT external_league_trades_num_sides_check CHECK ((number_sides >= 2))
);


--
-- Name: TABLE external_league_trades; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.external_league_trades IS 'Completed trades observed in external leagues. One row per trade; the exchanged bundles live in external_league_trade_legs.';


--
-- Name: external_league_users; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.external_league_users (
    platform character varying(20) NOT NULL,
    external_user_id character varying(64) NOT NULL,
    last_crawled_at timestamp with time zone,
    first_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    display_name text,
    is_bot boolean
);


--
-- Name: TABLE external_league_users; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.external_league_users IS 'Managers observed in external leagues, as crawl-graph nodes. last_crawled_at NULL is the unexplored frontier. Deliberately carries no profile fields.';


--
-- Name: external_leagues; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.external_leagues (
    platform character varying(20) NOT NULL,
    external_league_id character varying(64) NOT NULL,
    season_year smallint NOT NULL,
    league_name text,
    number_teams smallint,
    league_format character varying(10) NOT NULL,
    is_superflex boolean DEFAULT false NOT NULL,
    is_best_ball boolean DEFAULT false NOT NULL,
    points_per_reception numeric,
    tight_end_premium numeric,
    passing_touchdown_points numeric,
    taxi_slots smallint,
    roster_positions jsonb,
    scoring_settings jsonb,
    previous_external_league_id character varying(64),
    discovered_via character varying(20),
    last_synced_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    member_list_crawled_at timestamp with time zone,
    discovered_from_external_user_id character varying(64),
    has_individual_defensive_players boolean DEFAULT false NOT NULL,
    league_status character varying(20),
    last_message_at timestamp with time zone,
    external_draft_id character varying(32),
    league_settings jsonb,
    league_metadata jsonb,
    previous_external_league_unavailable_at timestamp with time zone,
    CONSTRAINT external_leagues_league_format_check CHECK (((league_format)::text = ANY ((ARRAY['dynasty'::character varying, 'keeper'::character varying, 'redraft'::character varying])::text[])))
);


--
-- Name: TABLE external_leagues; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.external_leagues IS 'Fantasy leagues on external platforms observed for realized trade data. We are not members of these leagues; they are read from public read-only APIs.';


--
-- Name: COLUMN external_leagues.member_list_crawled_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.external_leagues.member_list_crawled_at IS 'When /league/{id}/users was last fetched for this league. NULL = frontier league whose member list has never been read.';


--
-- Name: COLUMN external_leagues.discovered_from_external_user_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.external_leagues.discovered_from_external_user_id IS 'The manager whose league list surfaced this league. NULL for seed, previous-season chain links, and pre-crawl-graph rows.';


--
-- Name: COLUMN external_leagues.has_individual_defensive_players; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.external_leagues.has_individual_defensive_players IS 'League starts individual defensive players. Excluded from the value fit: IDP legs resolve to a NULL pid, which biases the affected side cheap in a one-directional way.';


--
-- Name: COLUMN external_leagues.last_message_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.external_leagues.last_message_at IS 'Weak liveness proxy: Sleeper system messages (waiver runs) bump this, so it partly measures automation rather than human engagement';


--
-- Name: format_category_signal_mapping; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.format_category_signal_mapping (
    format_category smallint NOT NULL,
    ktc_quarterback_axis smallint NOT NULL,
    ranking_type text NOT NULL,
    props_scoring_formula_template text,
    average_draft_position_format_id text
);


--
-- Name: TABLE format_category_signal_mapping; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.format_category_signal_mapping IS 'Static 6-row mapping from format_category to per-source axis: ktc qb=1|2, Sleeper adp_type, FantasyPros ranking_type, props scoring template. Runtime joins look this up to select the right source rows per format category.';


--
-- Name: historical_injury_index; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.historical_injury_index (
    pid character varying(25) NOT NULL,
    season_year smallint NOT NULL,
    week smallint NOT NULL,
    esbid integer NOT NULL,
    nfl_team character varying(3),
    is_played boolean,
    snap_count integer,
    snaps_offense smallint,
    snaps_defense smallint,
    snaps_special_teams smallint,
    is_gamelog_active boolean,
    is_ruled_out_in_game boolean,
    has_practice_listed_injury boolean,
    is_practice_questionable_or_worse boolean,
    practice_designation character varying(16),
    has_changelog_injury_event boolean,
    is_changelog_unavailable boolean,
    has_changelog_nfl_reserve_event boolean,
    missed_reason character varying(24),
    source_concurrence smallint,
    confidence character varying(8),
    inserted_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL
)
PARTITION BY RANGE (season_year);


