    weeks_covid_reserve smallint DEFAULT 0 NOT NULL,
    weeks_started smallint DEFAULT 0 NOT NULL,
    projected_points_added_at_acquisition numeric(6,1),
    realized_points_added_net_through_termination numeric(6,1),
    realized_points_added_positive_through_termination numeric(6,1),
    realized_points_added_net_in_active_slot numeric(6,1),
