    max_roster_wide_receiver smallint NOT NULL,
    max_roster_tight_end smallint NOT NULL,
    max_roster_defense_special_teams smallint NOT NULL,
    max_roster_kicker smallint NOT NULL,
    starting_free_agent_acquisition_budget integer NOT NULL,
    franchise_tag_limit smallint DEFAULT '1'::smallint NOT NULL,
    rookie_tag_limit smallint DEFAULT '1'::smallint NOT NULL,
    restricted_free_agency_tag_limit smallint DEFAULT '2'::smallint NOT NULL,
    season_due_amount bigint,
    wildcard_round smallint,
    championship_round integer[],
    rookie_draft_completed_at timestamp with time zone,
    season_finalized_at timestamp with time zone,
    scoring_format_id text NOT NULL,
    league_format_id text NOT NULL,
    restricted_free_agency_first_window_at timestamp with time zone,
    restricted_free_agency_window_hours smallint DEFAULT 24 NOT NULL,
    restricted_free_agency_processing_lead_hours smallint DEFAULT 3 NOT NULL,
    playoff_team_count smallint DEFAULT 6 NOT NULL,
    bye_count smallint DEFAULT 2 NOT NULL,
    bye_candidate_pool text DEFAULT 'league'::text NOT NULL,
    bye_selection_method text DEFAULT 'head_to_head'::text NOT NULL,
    at_large_selection_method text DEFAULT 'head_to_head'::text NOT NULL,
    has_division_winner_berths boolean DEFAULT false NOT NULL,
    trade_veto_window_hours smallint DEFAULT 24 NOT NULL,
    draft_pick_interval smallint DEFAULT 1,
    restricted_free_agency_processing_paused_until timestamp with time zone,
    restricted_free_agency_processing_paused_reason text,
    restricted_free_agency_processing_paused_at timestamp with time zone,
    head_to_head_berth_count smallint DEFAULT 0 NOT NULL,
    rookie_draft_end_at timestamp with time zone,
    auction_block_notice_minutes smallint DEFAULT 60 NOT NULL,
    auction_final_block_pace_minutes smallint DEFAULT 2 NOT NULL,
    auction_final_block_buffer_hours smallint DEFAULT 3 NOT NULL,
    is_auction_election_mode_enabled boolean DEFAULT false NOT NULL,
    CONSTRAINT auction_block_notice_within_a_day CHECK (((auction_block_notice_minutes > 0) AND (auction_block_notice_minutes <= 1440))),
    CONSTRAINT auction_final_block_buffer_within_bounds CHECK (((auction_final_block_buffer_hours > 0) AND (auction_final_block_buffer_hours <= 3))),
    CONSTRAINT auction_final_block_pace_positive CHECK (((auction_final_block_pace_minutes > 0) AND (auction_final_block_pace_minutes <= 60))),
    CONSTRAINT rfa_processing_pause_states_a_reason CHECK ((((restricted_free_agency_processing_paused_at IS NULL) AND (restricted_free_agency_processing_paused_reason IS NULL) AND (restricted_free_agency_processing_paused_until IS NULL)) OR ((restricted_free_agency_processing_paused_at IS NOT NULL) AND (restricted_free_agency_processing_paused_reason IS NOT NULL)))),
    CONSTRAINT rfa_processing_precedes_announcement CHECK (((restricted_free_agency_processing_lead_hours >= 1) AND (restricted_free_agency_processing_lead_hours < restricted_free_agency_window_hours))),
    CONSTRAINT rfa_window_divides_day CHECK ((restricted_free_agency_window_hours = ANY (ARRAY[1, 2, 3, 4, 6, 8, 12, 24]))),
    CONSTRAINT seasons_at_large_selection_method_known CHECK ((at_large_selection_method = ANY (ARRAY['head_to_head'::text, 'all_play'::text, 'points_for'::text]))),
    CONSTRAINT seasons_bye_candidate_pool_known CHECK ((bye_candidate_pool = ANY (ARRAY['league'::text, 'division_winners'::text]))),
    CONSTRAINT seasons_bye_count_within_playoff_field CHECK (((bye_count >= 0) AND (bye_count <= playoff_team_count))),
    CONSTRAINT seasons_bye_selection_method_known CHECK ((bye_selection_method = ANY (ARRAY['head_to_head'::text, 'all_play'::text]))),
    CONSTRAINT seasons_head_to_head_berth_count_within_field CHECK (((head_to_head_berth_count >= 0) AND (head_to_head_berth_count <= (playoff_team_count - bye_count)))),
    CONSTRAINT seasons_rookie_draft_end_at_set_with_start CHECK (((draft_start IS NULL) OR (rookie_draft_end_at IS NOT NULL)))
);


